from pathlib import Path

import dronekit

MODELS_DIR = Path(__file__).resolve().parent.parent / "models"

# Hand-edited network settings (drone/GS IPs and ports, localInfo)
NETWORK_CONFIG_PATH = str(MODELS_DIR / "network_config.json")
# Generated by choreography/lla_to_config.py -- do not edit by hand
SHOW_PATH = str(MODELS_DIR / "show.json")

# Frames lower than this at the start of the show (drones still on the
# ground) are skipped, so takeoff climbs straight to the first airborne frame.
# TODO: remove once timed playback handles takeoff itself
MIN_FRAME_ALT_M = 1.0


class Config:
    frames: list[list[dronekit.LocationGlobalRelative]]
    ips: list[str]

    def __init__(
        self,
        frames: list[list[dronekit.LocationGlobalRelative]],
        ips: list[str],
    ):
        self.frames = frames
        self.ips = ips
